# DK MAF.  Mariager - Fårup
#
let mf = path("d3.dk.maf");

with detail = 3, railway = :first :museum {
    with link = "point.dk.Mariager", railway = :station {
        track(mf[:mar - 0.5sw, :mar + 0.5sw]);
        marker(:left :de.bf, mf[:mar] << 0.5mt);
        slabel(:right :bold, mf[:mar - 0.5sw] >> 0.5mt + (1dt, -0.5dt),
            "Mariager"
        );
    }

    with link = "line.dk.MAF" {
        track(mf[:mar + 0.49sw, :bad - 0.49sw]);
    }

    with link = "point.dk.Ved-badestranden", railway = :station {
        track(mf[:bad - 0.5sw, :bad + 0.5sw]);
        marker(:left :de.hp :removed, mf[:bad] << 0.5mt);
        slabel(:left :removed, mf[:bad] >> 0.5mt + (-1.5dt, 0.5dt),
            "Ved badestranden"
        );
    }

    with link = "line.dk.MAF" {
        track(mf[:bad + 0.49sw, :bad + 1.51km]);
        line_label(:right:e, mf[:bad + 1.5km] >> 0.5mt, "MAF");
        track(mf[:bad + 1.49km, :lun - 0.49sw]);
    }

    with link = "point.dk.", railway = :station {
        track(mf[:lun - 0.5sw, :lun + 0.5sw]);
        marker(:right :de.hp, mf[:lun] >> 0.5mt);
        slabel(:left, mf[:lun] >> 0.5mt >> 1sh + (-1.3dt, 1.2dt),
            "Lunddalen*"
        );
    }

    with link = "line.dk.MAF" {
        track(mf[:lun + 0.49sw, :fje - 0.49sw]);
    }

    with link = "point.dk.Fjelsted", railway = :station {
        track(mf[:fje - 0.5sw, :fje + 0.5sw]);
        marker(:right :de.hp, mf[:fje] >> 0.5mt);
        slabel(:left, mf[:fje] >> 0.5mt >> 1sh + (-1.5dt, 0.8dt),
            "Fjelsted"
        );
    }

    with link = "line.dk.MAF" {
        track(mf[:fje + 0.49sw, :tru - 0.49sw]);
    }

    with link = "point.dk.True", railway = :station {
        track(mf[:tru - 0.5sw, :tru + 0.5sw]);
        marker(:right :de.bf, mf[:tru] >> 0.5mt);
        slabel(:top, mf[:tru] >> 0.5mt >> 1sh + (-0.5dt, -0.2dt),
            "True"
        );
    }

    with link = "line.dk.MAF" {
        track(mf[:tru + 0.49sw, :bro - 0.49sw]);
    }

    with link = "point.dk.Brødløs", railway = :station {
        track(mf[:bro - 0.5sw, :bro + 0.5sw]);
        marker(:right :de.hp, mf[:bro] >> 0.5mt);
        slabel(:left, mf[:bro] >> 0.5mt >> 1sh + (-0.5dt, 0.2dt),
            "Brødløs*"
        );
    }

    with link = "line.dk.MAF" {
        track(mf[:bro + 0.49sw, :vto - 0.49sw]);
    }

    with link = "point.dk.Vester-Tørslev", railway = :station {
        track(mf[:vto - 0.5sw, :vto + 0.5sw]);
        marker(:right :de.hp, mf[:vto] >> 0.5mt);
        marker(:right :de.exbf, mf[:vto] >> 0.5mt);
        slabel(:left, mf[:vto] >> 0.5mt >> 1.4sh + (-1.3dt, 0.6dt),
            "Vester Tørslev"
        );
    }

    with link = "line.dk.MAF" {
        track(mf[:vto + 0.49sw, :fru - 0.49sw]);
    }

    with link = "point.dk.Frugtplantagen", railway = :station {
        track(mf[:fru - 0.5sw, :fru + 0.5sw]);
        marker(:right :de.hp :removed, mf[:fru] >> 0.5mt);
        slabel(:left :removed, mf[:fru] >> 0.5mt >> 1sh + (-1.4dt, 0.5dt),
            "Frugtplantagen"
        );
    }

    with link = "line.dk.MAF" {
        track(mf[:fru + 0.49sw, :gle - 0.49sw]);
    }

    with link = "point.dk.Glenstrup", railway = :station {
        track(mf[:gle - 0.5sw, :gle + 0.5sw]);
        marker(:right :de.hp, mf[:gle] >> 0.5mt);
        slabel(:right, mf[:gle] << 0.5mt + (0.8dt, 2.3dt),
            "Glenstrup"
        );
    }

    with link = "line.dk.MAF" {
        track(mf[:gle + 0.49sw, :gle + 1.01km]);
        line_label(:left:n, mf[:gle + 1km] << 0.5mt, "MAF");
        track(mf[:gle + 0.99km, :han - 0.49sw]);
    }

    with link = "point.dk.Handest", railway = :station {
        track(mf[:han - 0.5sw, :han + 0.5sw]);
        marker(:left :de.bf, mf[:han] << 0.5mt);
        slabel(:left :bold, mf[:han] >> 0.5mt + (1dt, -1dt),
            "Handest"
        );
    }
}

with detail = 3, railway = :first :pax :closed {
    with link = "line.dk.MAF" {
        track(mf[:han + 0.49sw, :far.xm - 1md]);
        track(:ror,
                mf[:far.xm - 1.1md, :far.xm - 1md]
            ..  mf[:far.ym, :far.ym + 0.1dl] << 0.5md << 1ms << 0.5mt
        );
        track(:ror, mf[:far.ym, :far - 0.49sw] << 0.5md << 1ms << 0.5mt);
    }

    # point.dk.Fårup  dk.FFH
}

